    private static final Node[][] TREES = parse(TREE_DATA);

    /** Runs the input through all 40 trees and returns every crop ranked by confidence, highest first. */
    public static List<Prediction> predict(double[] x) {
        double[] totals = new double[CLASSES.length];
        for (Node[] tree : TREES) {
            int i = 0;
            int guard = 0;
            while (!tree[i].leaf) {
                Node n = tree[i];
                i = (x[n.feature] <= n.threshold) ? n.left : n.right;
                if (++guard > 200) break; // safety against malformed data
            }
            float[] p = tree[i].probs;
            for (int c = 0; c < p.length; c++) totals[c] += p[c];
        }
        List<Prediction> ranked = new ArrayList<>();
        for (int c = 0; c < CLASSES.length; c++) {
            ranked.add(new Prediction(CLASSES[c], totals[c] / TREES.length));
        }
        ranked.sort((a, b) -> Double.compare(b.confidence, a.confidence));
        return ranked;
    }

    private static Node[][] parse(String data) {
        String[] treeLines = data.split("\\n");
        Node[][] result = new Node[treeLines.length][];
        for (int t = 0; t < treeLines.length; t++) {
            String[] nodeStrs = treeLines[t].split(";");
            Node[] nodes = new Node[nodeStrs.length];
            for (int i = 0; i < nodeStrs.length; i++) {
                String[] f = nodeStrs[i].split(",");
                Node n = new Node();
                if (f[0].equals("S")) {
                    n.leaf = false;
                    n.feature = Integer.parseInt(f[1]);
                    n.threshold = Double.parseDouble(f[2]);
                    n.left = Integer.parseInt(f[3]);
                    n.right = Integer.parseInt(f[4]);
                } else {
                    n.leaf = true;
                    n.probs = new float[CLASSES.length];
                    for (int k = 1; k < f.length; k++) {
                        String[] cp = f[k].split(":");
                        n.probs[Integer.parseInt(cp[0])] = Float.parseFloat(cp[1]);
                    }
                }
                nodes[i] = n;
            }
            result[t] = nodes;
        }
        return result;
    }

